210	diff --git a/lib/features/entries/domain/entities/pending_entry_write.dart b/lib/features/entries/domain/entities/pending_entry_write.dart
211	new file mode 100644
212	index 0000000..28ad25b
213	--- /dev/null
214	+++ b/lib/features/entries/domain/entities/pending_entry_write.dart
215	@@ -0,0 +1,126 @@
216	+import '../../../../core/failure/failure.dart';
217	+import 'entry.dart';
218	+
219	+/// A [PendingEntryWrite]'s own lifecycle — exactly the two states spec-4-2
220	+/// needs (Boundaries: "status = inFlight or failed(Failure)"). A write that
221	+/// resolves successfully is never represented here at all: `PendingEntry
222	+/// WriteTracker.create()`/`retry()` drop the record outright on success
223	+/// (Boundaries: "tracker drops the record") rather than modeling a third
224	+/// "confirmed" variant — nothing downstream ever needs to render a pending
225	+/// write as confirmed, only to stop rendering it as pending.
226	+sealed class PendingEntryWriteStatus {
227	+  const PendingEntryWriteStatus();
228	+}
229	+
230	+/// The write is in flight — `create()`/`retry()` already called the
231	+/// repository, no response yet.
232	+class PendingEntryWriteInFlight extends PendingEntryWriteStatus {
233	+  const PendingEntryWriteInFlight();
234	+
235	+  @override
236	+  bool operator ==(Object other) => other is PendingEntryWriteInFlight;
237	+
238	+  @override
239	+  int get hashCode => (PendingEntryWriteInFlight).hashCode;
240	+
241	+  @override
242	+  String toString() => 'PendingEntryWriteInFlight()';
243	+}
244	+
245	+/// The write's last attempt failed — [failure] is kept verbatim so a later
246	+/// retry can replay the exact same payload, and so `deriveSyncBadgeState()`
247	+/// can read [Failure.retryable] off it directly (Boundaries: "Tap on error
248	+/// badge: if `failure.retryable`...").
249	+class PendingEntryWriteFailed extends PendingEntryWriteStatus {
250	+  const PendingEntryWriteFailed({required this.failure});
251	+
252	+  final Failure failure;
253	+
254	+  @override
255	+  bool operator ==(Object other) =>
256	+      identical(this, other) ||
257	+      (other is PendingEntryWriteFailed && other.failure == failure);
258	+
259	+  @override
260	+  int get hashCode => failure.hashCode;
261	+
262	+  @override
263	+  String toString() => 'PendingEntryWriteFailed(failure: $failure)';
264	+}
265	+
266	+/// A capture write (`TextEntryCubit`/`AudioEntryCubit`/`PhotoEntryCubit`'s
267	+/// own `save()`) that `PendingEntryWriteTracker` is currently tracking —
268	+/// either still in flight or failed-but-not-yet-retried (Intent). [tempId]
269	+/// is a client-generated id (`PendingEntryWriteTrackerImpl`'s own
270	+/// generator), never the server's real `Entry.id` — it exists only so
271	+/// [PendingEntryWriteTracker.retry] and `MeusRegistrosCubit`'s own per-card
272	+/// lookup (`MeusRegistrosLoaded.badgeFor`) have something stable to key on
273	+/// while the write has no server-assigned id yet.
274	+///
275	+/// Plain hand-rolled equality (existing convention — mirrors [Entry]/
276	+/// [EntryDateGroup], never `freezed`, Tasks: "hand-rolled equality
277	+/// (existing convention)").
278	+class PendingEntryWrite {
279	+  const PendingEntryWrite({
280	+    required this.tempId,
281	+    required this.content,
282	+    required this.source,
283	+    required this.mediaDurationSeconds,
284	+    required this.startedAt,
285	+    required this.status,
286	+  });
287	+
288	+  final String tempId;
289	+  final String content;
290	+  final EntrySource source;
291	+
292	+  /// Carried through verbatim for a retry's own replayed `create()` call —
293	+  /// mirrors [Entry.mediaDurationSeconds]'s own "non-null only for audio"
294	+  /// contract.
295	+  final int? mediaDurationSeconds;
296	+
297	+  /// When this write first started — also doubles as the placeholder
298	+  /// card's own `occurredAt` while pending (`MeusRegistrosLoaded`'s own
299	+  /// placeholder-`Entry` construction), so a pending write always renders
300	+  /// at the top of "Hoje" until it resolves.
301	+  final DateTime startedAt;
302	+
303	+  final PendingEntryWriteStatus status;
304	+
305	+  PendingEntryWrite copyWith({PendingEntryWriteStatus? status}) =>
306	+      PendingEntryWrite(
307	+        tempId: tempId,
308	+        content: content,
309	+        source: source,
310	+        mediaDurationSeconds: mediaDurationSeconds,
311	+        startedAt: startedAt,
312	+        status: status ?? this.status,
313	+      );
314	+
315	+  @override
316	+  bool operator ==(Object other) =>
317	+      identical(this, other) ||
318	+      (other is PendingEntryWrite &&
319	+          other.tempId == tempId &&
320	+          other.content == content &&
321	+          other.source == source &&
322	+          other.mediaDurationSeconds == mediaDurationSeconds &&
323	+          other.startedAt == startedAt &&
324	+          other.status == status);
325	+
326	+  @override
327	+  int get hashCode => Object.hash(
328	+    tempId,
329	+    content,
330	+    source,
331	+    mediaDurationSeconds,
332	+    startedAt,
333	+    status,
334	+  );
335	+
336	+  @override
337	+  String toString() =>
338	+      'PendingEntryWrite(tempId: $tempId, content: $content, source: '
339	+      '$source, mediaDurationSeconds: $mediaDurationSeconds, startedAt: '
340	+      '$startedAt, status: $status)';
341	+}
342	diff --git a/lib/features/entries/domain/entities/sync_badge_state.dart b/lib/features/entries/domain/entities/sync_badge_state.dart
343	new file mode 100644
344	index 0000000..a6a8453
345	--- /dev/null
346	+++ b/lib/features/entries/domain/entities/sync_badge_state.dart
347	@@ -0,0 +1,102 @@
348	+import '../../../../core/failure/failure.dart';
349	+import 'entry.dart';
350	+import 'pending_entry_write.dart';
351	+
352	+/// A single `EntryRecordCard`'s own sync badge (AD-10) — exactly the 3
353	+/// states `docs/input/backend/sync-badge.md` names, never a 4th: the
354	+/// server exposes no sync field of its own, so these 3 are the complete
355	+/// set this app ever needs to render. Sealed, with `const factory`
356	+/// constructors on the base class (mirrors `Failure`'s own shape, minus
357	+/// the `freezed` codegen — no `==`/`copyWith` machinery is needed here
358	+/// beyond the hand-rolled equality each subclass already carries) so call
359	+/// sites read as `SyncBadgeState.synchronizing()` rather than naming each
360	+/// subclass directly.
361	+sealed class SyncBadgeState {
362	+  const SyncBadgeState();
363	+
364	+  const factory SyncBadgeState.synchronizing() = SyncBadgeSynchronizing;
365	+
366	+  const factory SyncBadgeState.synchronized() = SyncBadgeSynchronized;
367	+
368	+  const factory SyncBadgeState.error(Failure failure) = SyncBadgeError;
369	+}
370	+
371	+/// "Synchronizing" (ochre) — a local write not yet confirmed by the
372	+/// server.
373	+class SyncBadgeSynchronizing extends SyncBadgeState {
374	+  const SyncBadgeSynchronizing();
375	+
376	+  @override
377	+  bool operator ==(Object other) => other is SyncBadgeSynchronizing;
378	+
379	+  @override
380	+  int get hashCode => (SyncBadgeSynchronizing).hashCode;
381	+
382	+  @override
383	+  String toString() => 'SyncBadgeSynchronizing()';
384	+}
385	+
386	+/// "Synchronized" (green) — nothing pending for this entry; the last
387	+/// confirmed write matched.
388	+class SyncBadgeSynchronized extends SyncBadgeState {
389	+  const SyncBadgeSynchronized();
390	+
391	+  @override
392	+  bool operator ==(Object other) => other is SyncBadgeSynchronized;
393	+
394	+  @override
395	+  int get hashCode => (SyncBadgeSynchronized).hashCode;
396	+
397	+  @override
398	+  String toString() => 'SyncBadgeSynchronized()';
399	+}
400	+
401	+/// "Synchronization error" (red) — the write was attempted and failed,
402	+/// never yet reconciled. [failure] is kept so the badge's own tap handler
403	+/// (`SyncBadge`) can read [Failure.retryable]/[Failure.message] directly,
404	+/// per the Boundaries' "Tap on error badge" rule.
405	+class SyncBadgeError extends SyncBadgeState {
406	+  const SyncBadgeError(this.failure);
407	+
408	+  final Failure failure;
409	+
410	+  @override
411	+  bool operator ==(Object other) =>
412	+      identical(this, other) ||
413	+      (other is SyncBadgeError && other.failure == failure);
414	+
415	+  @override
416	+  int get hashCode => failure.hashCode;
417	+
418	+  @override
419	+  String toString() => 'SyncBadgeError(failure: $failure)';
420	+}
421	+
422	+/// The one place this app ever decides a card's badge (Never: "any screen
423	+/// recomputing badge state inline") — pure, no I/O, no `package:flutter`
424	+/// import (RNF06).
425	+///
426	+/// [pending] wins whenever it's non-null, regardless of [entry] — per
427	+/// `sync-badge.md`, "Synchronizing"/"Synchronization error" both describe
428	+/// *client-side pending state*, not anything read off [entry] itself, so a
429	+/// pending write's own status is always the authoritative answer for
430	+/// whichever card it belongs to. Once [pending] is `null`, the existence of
431	+/// a confirmed [entry] already means "it is on the server" (sync-
432	+/// badge.md: "it is on the server already means synchronized, by
433	+/// definition") -> [SyncBadgeSynchronized]. [entry] and [pending] both
434	+/// `null` is unreachable from every real caller (`MeusRegistrosLoaded`
435	+/// always derives a displayed card from one or the other, never neither)
436	+/// but still resolves to [SyncBadgeSynchronized] rather than throwing
437	+/// (RNF09-style defensiveness) — "nothing pending" is the closest true
438	+/// reading of that combination regardless of [entry].
439	+SyncBadgeState deriveSyncBadgeState(Entry? entry, PendingEntryWrite? pending) {
440	+  if (pending != null) {
441	+    return switch (pending.status) {
442	+      PendingEntryWriteInFlight() => const SyncBadgeState.synchronizing(),
443	+      PendingEntryWriteFailed(failure: final failure) => SyncBadgeState.error(
444	+        failure,
445	+      ),
446	+    };
447	+  }
448	+  return const SyncBadgeState.synchronized();
449	+}
