452	index 0000000..a9460ff
453	--- /dev/null
454	+++ b/lib/features/entries/domain/services/pending_entry_write_tracker.dart
455	@@ -0,0 +1,233 @@
456	+// The constructor keeps the public named param (`repository`) distinct
457	+// from the private field it initializes, matching `session_repository_
458	+// impl.dart`'s/`auth_repository_impl.dart`'s documented convention.
459	+// ignore_for_file: prefer_initializing_formals
460	+import 'dart:async';
461	+
462	+import 'package:fpdart/fpdart.dart';
463	+
464	+import '../../../../core/failure/failure.dart';
465	+import '../entities/entry.dart';
466	+import '../entities/pending_entry_write.dart';
467	+import '../repositories/entries_repository.dart';
468	+
469	+/// The single `create()`/`retry()` entry point for all three capture
470	+/// cubits (`TextEntryCubit`/`AudioEntryCubit`/`PhotoEntryCubit`) — Intent:
471	+/// "the tracker, not `MeusRegistrosCubit`, owns reconciliation". Pure
472	+/// Dart, no `package:flutter`/`data` import (RNF06) — a port+impl pair in
473	+/// one file, same structural convention `SessionExpiryNotifier`/
474	+/// `SessionExpiryNotifierImpl` already use.
475	+abstract class PendingEntryWriteTracker {
476	+  /// Identical contract to [EntriesRepository.create] (Boundaries) — every
477	+  /// capture cubit swaps its `EntriesRepository` dependency for this one,
478	+  /// with no other call-site change. Internally: records an optimistic
479	+  /// [PendingEntryWrite] (status [PendingEntryWriteInFlight]) *before*
480	+  /// calling through to the repository, so [pendingWrites] reflects it
481	+  /// immediately; on success, drops the record and emits the confirmed
482	+  /// [Entry] on [confirmedWrites]; on failure, flips the record to
483	+  /// [PendingEntryWriteFailed] and leaves it for [retry].
484	+  Future<Either<Failure, Entry>> create({
485	+    required String content,
486	+    required EntrySource source,
487	+    int? mediaDurationSeconds,
488	+  });
489	+
490	+  /// Replays the exact same payload a failed write ([tempId]) was created
491	+  /// with (Never: "a second retry endpoint — retry replays `create()`
492	+  /// verbatim"). A no-op for an unknown [tempId] or one that isn't
493	+  /// currently [PendingEntryWriteFailed] (e.g. already in flight, or
494	+  /// already resolved).
495	+  Future<void> retry(String tempId);
496	+
497	+  /// Releases the underlying stream resources — wired into `get_it`'s own
498	+  /// reset lifecycle (`entries_injection.dart`'s `dispose:`), same
499	+  /// convention `SessionExpiryNotifier.dispose()`/`SessionRepository.
500	+  /// dispose()` already use.
